            "text": "Goalaz - Branding\n\nA logo and brand identity have been designed by Element for the sports betting company \"Goalaz\".  For their betting amusement, users of the \"Goalaz\" website can anticipate exciting virtual sports, instant games, and draws in addition to traditional sports. \"Goalaz\" creates an intriguing and dynamic betting environment that matches the enthusiasm of sports fans across the globe.\n\nAgency: Element Visual Studio\n\nLogo & Creative Direction | Adam Yunisov\n\nArt Direction & 3D visualization | Hatam Yunisli\n\nBranding | Jalal Mammadov\n\nAnimation | Onur Yunisli\n\nProject  | elementvs.com",
